<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">E</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary">
      <a href="index.html">Home</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html" class="active">Essences</a>
      <a href="shop.html">Boutique</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <div>
        <h1>Essences crafted for daily rituals</h1>
        <p class="muted">A small collection of single oils and pre-blended profiles. Each listing includes usage notes, dilution guidance, and pet/pregnancy cautions when relevant.</p>
      </div>
      <div style="margin-left:auto">
        <button class="btn" onclick="location.href='shop.html'" style="padding:10px 14px;border-radius:9px;border:0;background:var(--accent);color:#fff;cursor:pointer">Visit Boutique</button>
      </div>
    </div>

    <section aria-labelledby="collection-h">
      <h2 id="collection-h">Featured blends</h2>
      <div class="grid">
        <article class="card" data-keywords="calm,evening,lavender">
          <h3>Evening Ease — gentle blend</h3>
          <div class="muted">Notes: lavender, petitgrain, a soft cedar whisper.</div>
          <p class="muted">Suggested use: diffuse briefly in the evening or dilute to 1% for a pulse point roll-on. Patch test before topical use.</p>
          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <span class="badge">Safety: low-risk (adults)</span>
            <a href="blends.html#evening-ease" style="margin-left:auto;color:var(--accent);text-decoration:none">Read details</a>
          </div>
        </article>

        <article class="card" data-keywords="bright,focus,citrus">
          <h3>Morning Clarity — citrus lift</h3>
          <div class="muted">Notes: sweet orange, rosemary (low), bergamot (non-furocoumarin source).</div>
          <p class="muted">Suggested use: a 0.5–1% diffuser blend for brief morning routines. Avoid direct sunlight after topical application if using bergamot-type oils.</p>
          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <span class="badge">Safety: avoid in pregnancy without guidance</span>
            <a href="blends.html#morning-clarity" style="margin-left:auto;color:var(--accent);text-decoration:none">Read details</a>
          </div>
        </article>

        <article class="card" data-keywords="clarity,focus,herbal">
          <h3>Clear Desk — study blend</h3>
          <div class="muted">Notes: rosemary (low), lemon, a hint of eucalyptus (low concentration).</div>
          <p class="muted">Suggested use: short diffuser bursts while working. Keep concentrations low and ventilate the space.</p>
          <div style="margin-top:10px;display:flex;gap:8px;align-items:center">
            <span class="badge">Safety: not for household with birds</span>
            <a href="blends.html#clear-desk" style="margin-left:auto;color:var(--accent);text-decoration:none">Read details</a>
          </div>
        </article>
      </div>
    </section>

    <section aria-labelledby="howto-h">
      <h2 id="howto-h">How we label safety</h2>
      <div class="card" style="margin-top:12px">
        <p class="muted">Every blend card lists suggested dilutions and notes on pets, pregnancy, and sun sensitivity when applicable. We avoid medical promises and instead describe how scents may support attentional shifts or ritual cues for some people.</p>
      </div>
    </section>

    <section aria-label="Call to action">
      <div class="card" style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <strong>Want a custom blend for your cohort?</strong>
          <div class="muted">We create small-batch profiles for groups with a focus on safety and repeatability.</div>
        </div>
        <div>
          <a class="btn" href="book.html">Book a consult</a>
        </div>
      </div>
    </section>

    <footer>
      <div class="muted">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call {{PHONE}} • Serving {{CITY}}, {{STATE}}</div>
    </footer>
  </main>

  <script>
    // Simple client-side search + reveals
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if(prefersReduced){ document.querySelectorAll('section').forEach(s=>s.classList.add('revealed')); } else {
        const obs = new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');obs.unobserve(e.target);}})},{threshold:0.12});
        document.querySelectorAll('section').forEach(s=>obs.observe(s));
      }

      // Tiny search
      const cards = Array.from(document.querySelectorAll('.card'));
      const input = document.createElement('input'); input.type='text'; input.placeholder='Search blends…'; input.style.padding='10px'; input.style.width='100%'; input.style.borderRadius='10px'; input.style.border='1px solid rgba(0,0,0,0.06)';
      const hero = document.querySelector('.hero');
      hero.insertAdjacentElement('afterend', input);
      input.addEventListener('input',()=>{
        const q = input.value.toLowerCase().trim();
        cards.forEach(c=>{ const txt = (c.textContent||'').toLowerCase(); c.style.display = txt.includes(q)?'block':'none'; });
      });
    })();
  </script>
</body>
</html>"}}
