<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Boutique — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Small-batch aromatherapy goods and accessories with clear usage guidance.">
  <style>
    :root{--bg:#fbfbfb;--muted:#5a5a5a;--accent:#726b9a;--card:#fff}
    *{box-sizing:border-box}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:var(--bg);color:#111}
    header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{margin-left:10px;color:var(--muted);text-decoration:none}
    main{max-width:980px;margin:28px auto;padding:0 18px}

    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}
    .product{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 18px rgba(0,0,0,0.04)}
    .product h3{margin:0 0 6px}
    .price{font-weight:700;color:var(--accent)}
    .small{font-size:0.9rem;color:var(--muted)}

    .filters{display:flex;gap:8px;margin-bottom:16px}
    select,button{padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.06)}

    /* reveal */
    section{opacity:0;transform:translateY(12px);transition:opacity .5s ease,transform .5s ease}
    section.revealed{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){section{opacity:1;transform:none;transition:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:10px">
      <div style="width:44px;height:44px;border-radius:8px;background:linear-gradient(135deg,#e9dff3,#726b9a);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700">B</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
